def photosynthesis():
    from collections import deque
    def get_input():
        return input().split()
    def process_data(data):
        queue = deque(data)
        while queue:
            node = queue.popleft()
            if node[0] == 'F':
                yield node[1:]
            elif node[0] == 'B':
                if len(queue) > 0:
                    yield from process_data(queue[0])
                else:
                    yield node[1:]
    return list(process_data(get_input()))

